#!/usr/bin/env bash
#
# Upload a report generated by .github/tools/hyperfine-runs.sh.
# Configures Bencher's auto-scaling units: time_wall_clock in nanoseconds (ns)
# and memory_peak_resident in bytes (B).

set +x
set -euo pipefail

if [[ -z "${BENCHER_RUN_KEY:-}" ]]; then
    echo "ERROR: BENCHER_RUN_KEY must be set" >&2
    exit 1
fi
BENCHER_PROJECT=${BENCHER_PROJECT:-super-speedy-syslog-searcher}

if [[ ${#} -ne 1 ]]; then
    echo "ERROR: BENCHER_REPORT file path must be provided as an argument" >&2
    echo "Usage: $0 <BENCHER_REPORT>" >&2
    exit 1
fi

BENCHER_REPORT="$1"

if [[ ! -f "${BENCHER_REPORT}" ]]; then
    echo "ERROR: BENCHER_REPORT file does not exist: ${BENCHER_REPORT}" >&2
    exit 1
fi

declare out
out=$(mktemp)
readonly out
trap 'rm -f -- "${out}"' EXIT
declare -r api="https://api.bencher.dev/v0/projects/${BENCHER_PROJECT}"

function request() {
    if ! (set -x
        curl \
            --fail-with-body \
            --silent \
            --show-error \
            --header "Authorization: Bearer ${BENCHER_RUN_KEY}" \
            --header 'Content-Type: application/json' \
            --output "${out}" \
            "${@}"
    )
    then
        cat "${out}" >&2
        return 1
    fi
}

declare measure
declare units
declare matches
declare uuid
declare payload
for measure_unit in \
    'time_wall_clock|nanoseconds (ns)' \
    'memory_peak_resident|bytes (B)'
do
    measure="${measure_unit%%|*}"
    units="${measure_unit##*|}"
    echo "Processing measure: ${measure} with units: ${units}" >&2
    echo >&2
    request --get --data-urlencode "name=${measure}" "${api}/measures"
    matches=$(jq -e --arg name "${measure}" '
        if type == "array" and all(.[]; .name == $name) and length <= 1
        then . else error("unexpected measure lookup response") end
    ' "${out}")
    if [[ "$(jq 'length' <<< "${matches}")" -eq 0 ]]; then
        payload=$(jq -n --arg name "${measure}" --arg units "${units}" '{name: $name, units: $units}')
        request --request POST --data "${payload}" "${api}/measures"
    else
        uuid=$(jq -er '.[0].uuid' <<< "${matches}")
        payload=$(jq -n --arg units "${units}" '{units: $units}')
        request --request PATCH --data "${payload}" "${api}/measures/${uuid}"
    fi
    echo >&2
done

echo "Uploading report: ${BENCHER_REPORT}" >&2
echo >&2
request --data-binary @"${BENCHER_REPORT}" "${api}/reports"
jq '.' "${out}"
